L = lambda name, facts, desc: {"name": name, "facts": facts, "desc": desc}

def demo(slug, city, lng, lat, house):
    t_en, t_ru = ("Old house", "Старый дом") if house else ("Land plot", "Земельный участок")
    c = CITIES[city]
    return {"slug": slug, "kind": "object", "city": city, "lng": lng, "lat": lat,
            "en": L(f"Demo: {t_en.lower()}, {c['en']}", [("Type", t_en), ("Area", "on request"), ("Price", "on request")], ""),
            "ru": L(f"Демо: {t_ru.lower()}, {c['ru']}", [("Тип", t_ru), ("Площадь", "по запросу"), ("Стоимость", "по запросу")], "")}

